const LOW_SCORE = 2;

// The customer rates a resolved ticket 1 to 5, once. A ticket that does not exist and one of another organisation
// look the same: null. A score of LOW_SCORE or less tells the owner by email, if there is one.
function rateTicket(store, customer, id, score, { now = new Date() } = {}) {
  const t = getMyTicket(store, customer, id);
  if (!t) return null;
  if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('the score must be a whole number from 1 to 5');
  if (t.status !== STATUS.RESOLVED) throw new Error(`only a resolved ticket can be rated, this one is ${t.status}`);
  if (t.rating_score != null) throw new Error('this ticket is already rated');
  const updated = store.updateTicket(id, { rating_score: score, rated_at: now.toISOString() });
  if (score <= LOW_SCORE && updated.owner_id) notifyAgent(store, updated.owner_id, { type: 'low_rating', ticketId: id, score });
  return updated;
}
```

