'use strict';
// Nightly. Writes exports/agent-csat-weekly.json: for each agent, how many ratings their tickets received in the
// past seven days, and the average score. A ticket counts for its owner at the time the job runs; a ticket with no
// owner counts for nobody.
const fs = require('node:fs');
const path = require('node:path');
const { EXPORT_DIR } = require('./export-tickets');

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;

function weeklyCsat(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
  const since = now.getTime() - WINDOW_DAYS * DAY;
  const perAgent = new Map();
  for (const t of store.listTickets()) {
    if (t.rating_score == null || !t.owner_id) continue;
    if (new Date(t.rated_at).getTime() < since) continue;
    const acc = perAgent.get(t.owner_id) || { ratings: 0, sum: 0 };
    acc.ratings += 1;
    acc.sum += t.rating_score;
    perAgent.set(t.owner_id, acc);
  }
  const rows = [...perAgent.entries()]
    .sort(([a], [b]) => a - b)
    .map(([agent_id, { ratings, sum }]) => ({ agent_id, ratings, average: Math.round((sum / ratings) * 100) / 100 }));
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, 'agent-csat-weekly.json');
  fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
  return { file, rows };
}

module.exports = { weeklyCsat, WINDOW_DAYS };
```

